import{_ as a,c as s,o as t,ag as e}from"./chunks/framework.DPDPlp3K.js";const k=JSON.parse('{"title":"Intel T2 Mac 双系统安装 CachyOS","description":"","frontmatter":{},"headers":[],"relativePath":"notion/Intel T2 Mac 双系统安装 CachyOS.md","filePath":"notion/Intel T2 Mac 双系统安装 CachyOS.md"}'),l={name:"notion/Intel T2 Mac 双系统安装 CachyOS.md"};function p(n,i,h,c,o,d){return t(),s("div",null,i[0]||(i[0]=[e(`<h1 id="intel-t2-mac-双系统安装-cachyos" tabindex="-1">Intel T2 Mac 双系统安装 CachyOS <a class="header-anchor" href="#intel-t2-mac-双系统安装-cachyos" aria-label="Permalink to &quot;Intel T2 Mac 双系统安装 CachyOS&quot;">​</a></h1><p>本文记录在带 Apple T2 安全芯片的 Intel Mac 上保留 macOS，并安装 CachyOS 双系统的完整过程。</p><p>本文方案已在以下设备上实际验证：</p><table tabindex="0"><thead><tr><th>项目</th><th>配置</th></tr></thead><tbody><tr><td>机型</td><td>MacBook Pro 16-inch, 2019</td></tr><tr><td>Model Identifier</td><td><code>MacBookPro16,1</code></td></tr><tr><td>处理器</td><td>8-Core Intel Core i9</td></tr><tr><td>内存</td><td>64 GB</td></tr><tr><td>内置硬盘</td><td>500 GB Apple SSD</td></tr><tr><td>安装方式</td><td>macOS 250 GB + CachyOS 250 GB</td></tr><tr><td>Bootloader</td><td>systemd-boot</td></tr><tr><td>桌面环境</td><td>KDE Plasma</td></tr></tbody></table><blockquote><p>本文仅适用于 <code>x86_64</code> 架构并带 Apple T2 芯片的 Intel Mac。M1、M2、M3、M4 等 Apple Silicon 机型不能使用此方案。</p></blockquote><h2 id="_1-安装前须知" tabindex="-1">1. 安装前须知 <a class="header-anchor" href="#_1-安装前须知" aria-label="Permalink to &quot;1. 安装前须知&quot;">​</a></h2><h3 id="_1-1-推荐保留-macos" tabindex="-1">1.1 推荐保留 macOS <a class="header-anchor" href="#_1-1-推荐保留-macos" aria-label="Permalink to &quot;1.1 推荐保留 macOS&quot;">​</a></h3><p>不建议删除整个 macOS，原因包括：</p><ul><li>Apple Wi-Fi 和部分蓝牙固件需要从 macOS 合法提取；</li><li>macOS 更新可能同时更新设备固件；</li><li>macOS 可用于恢复系统和排查启动问题；</li><li>完全删除 macOS 会增加数据丢失和恢复失败的风险。</li></ul><p>开始前应使用 Time Machine 或其他方式完整备份重要数据。条件允许时，另外制作一个可启动的 macOS 安装 U 盘。</p><h3 id="_1-2-已知硬件限制" tabindex="-1">1.2 已知硬件限制 <a class="header-anchor" href="#_1-2-已知硬件限制" aria-label="Permalink to &quot;1.2 已知硬件限制&quot;">​</a></h3><p>T2 Mac 上的 Linux 可以日常使用，但仍有一些限制：</p><ul><li>Touch ID 不可用；</li><li>触控板没有 Force Touch，防误触效果不如 macOS；</li><li>蓝牙和睡眠在部分机型上可能不稳定；</li><li>带 AMD 独显的机型可能遇到混合显卡或电源管理问题；</li><li>内置麦克风输入音量可能较低。</li></ul><p>具体状态以 <a href="https://wiki.t2linux.org/state/" target="_blank" rel="noreferrer">t2linux 硬件支持列表</a> 为准。</p><h2 id="_2-确认机型" tabindex="-1">2. 确认机型 <a class="header-anchor" href="#_2-确认机型" aria-label="Permalink to &quot;2. 确认机型&quot;">​</a></h2><p>在 macOS 终端执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">uname</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -m</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">system_profiler</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> SPHardwareDataType</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> SPiBridgeDataType</span></span></code></pre></div><p>应满足以下条件：</p><ul><li><code>uname -m</code> 输出 <code>x86_64</code>；</li><li>Hardware Overview 中的处理器是 Intel；</li><li>Controller 或 iBridge 中显示 <code>Apple T2 安全芯片</code> 或 <code>Apple T2 chip</code>。</li></ul><p>Apple 官方列出的 T2 MacBook 主要包括 2018 至 2020 年发布的 Intel MacBook Pro 和 MacBook Air。具体可查看 <a href="https://support.apple.com/103265" target="_blank" rel="noreferrer">Apple T2 机型列表</a>。</p><h2 id="_3-准备安装介质" tabindex="-1">3. 准备安装介质 <a class="header-anchor" href="#_3-准备安装介质" aria-label="Permalink to &quot;3. 准备安装介质&quot;">​</a></h2><p>需要准备：</p><ul><li>一个至少 8 GB 的 U 盘，写入镜像时会被清空；</li><li>稳定的网络连接；</li><li>CachyOS Desktop ISO；</li><li>可选的 USB 有线网卡或手机 USB 网络共享。</li></ul><h3 id="_3-1-下载并验证-iso" tabindex="-1">3.1 下载并验证 ISO <a class="header-anchor" href="#_3-1-下载并验证-iso" aria-label="Permalink to &quot;3.1 下载并验证 ISO&quot;">​</a></h3><p>从 <a href="https://wiki.cachyos.org/cachyos_basic/download/" target="_blank" rel="noreferrer">CachyOS 官方下载页面</a>下载 Desktop ISO 和同名 <code>.sha256</code> 文件。</p><p>在 macOS 中验证：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D20F39;--shiki-light-font-style:italic;--shiki-dark:#F38BA8;--shiki-dark-font-style:italic;">cd</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ~/Downloads</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">shasum</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -a</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> 256</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> cachyos-desktop-linux-</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">*</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">.iso</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">cat</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> cachyos-desktop-linux-</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">*</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">.iso.sha256</span></span></code></pre></div><p>两个 SHA-256 值必须完全一致。不要把教程中的旧哈希直接用于新版本 ISO，应始终以本次下载的 <code>.sha256</code> 文件为准。</p><h3 id="_3-2-写入-u-盘" tabindex="-1">3.2 写入 U 盘 <a class="header-anchor" href="#_3-2-写入-u-盘" aria-label="Permalink to &quot;3.2 写入 U 盘&quot;">​</a></h3><p>推荐使用 balenaEtcher：</p><ol><li>选择 <code>Flash from file</code>，打开 CachyOS ISO；</li><li>选择正确的 U 盘；</li><li>点击 <code>Flash</code>；</li><li>写入完成后安全弹出 U 盘。</li></ol><p>选择目标盘时务必核对容量，避免覆盖其他磁盘。</p><h2 id="_4-在-macos-中提取-apple-固件" tabindex="-1">4. 在 macOS 中提取 Apple 固件 <a class="header-anchor" href="#_4-在-macos-中提取-apple-固件" aria-label="Permalink to &quot;4. 在 macOS 中提取 Apple 固件&quot;">​</a></h2><p>由于授权限制，CachyOS 不能在 ISO 中直接分发 Apple 的 Wi-Fi 固件。安装 Linux 前，在 macOS 终端执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">curl</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -sL</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> https://wiki.t2linux.org/tools/firmware.sh</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;"> |</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> bash</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -s</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> copy_to_efi</span></span></code></pre></div><p>脚本将执行以下操作：</p><ol><li>挂载 Apple EFI 分区；</li><li>从 macOS 获取 Wi-Fi 和蓝牙固件；</li><li>将固件和 <code>firmware.sh</code> 保存到 EFI 分区；</li><li>卸载 EFI 分区。</li></ol><p>看到类似以下输出表示成功：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>Getting Wi-Fi and Bluetooth firmware</span></span>
<span class="line"><span>Copying this script to EFI</span></span>
<span class="line"><span>Volume EFI ... unmounted</span></span></code></pre></div><p>这里只是把固件保存到 EFI，并不会自动把固件安装进 CachyOS。进入 Linux 后仍需手动运行脚本。</p><h2 id="_5-为-cachyos-创建磁盘空间" tabindex="-1">5. 为 CachyOS 创建磁盘空间 <a class="header-anchor" href="#_5-为-cachyos-创建磁盘空间" aria-label="Permalink to &quot;5. 为 CachyOS 创建磁盘空间&quot;">​</a></h2><h3 id="_5-1-使用磁盘工具缩小-macos" tabindex="-1">5.1 使用磁盘工具缩小 macOS <a class="header-anchor" href="#_5-1-使用磁盘工具缩小-macos" aria-label="Permalink to &quot;5.1 使用磁盘工具缩小 macOS&quot;">​</a></h3><p>在 macOS 中打开“磁盘工具”：</p><ol><li>点击“显示”并选择“显示所有设备”；</li><li>选择 <code>Macintosh HD</code> 所在的内部磁盘或 APFS 容器；</li><li>点击“分区”；</li><li>点击饼图下方的 <code>+</code>；</li><li>必须选择“添加分区”，不要选择“添加 APFS 宗卷”；</li><li>名称填写 <code>CachyOS</code>；</li><li>格式选择 <code>ExFAT</code>，方便在安装器中识别；</li><li>分配容量并应用。</li></ol><p>CachyOS 最低建议 50 GB。如果准备安装开发环境、游戏或虚拟机，建议分配 120 至 250 GB。</p><p>不要在 Linux 安装器中直接缩小 macOS 的 APFS 容器。</p><h3 id="_5-2-核对分区" tabindex="-1">5.2 核对分区 <a class="header-anchor" href="#_5-2-核对分区" aria-label="Permalink to &quot;5.2 核对分区&quot;">​</a></h3><p>在 macOS 终端执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">diskutil</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> list</span></span></code></pre></div><p>本次安装在分区前的磁盘结构如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>/dev/disk0</span></span>
<span class="line"><span>  disk0s1   EFI                         314.6 MB</span></span>
<span class="line"><span>  disk0s2   Apple_APFS Container        250.0 GB</span></span>
<span class="line"><span>  disk0s4   Microsoft Basic Data        250.0 GB  CachyOS</span></span></code></pre></div><p>其中：</p><ul><li><code>disk0s1</code> 是 Apple EFI，不能删除或格式化；</li><li><code>disk0s2</code> 是 macOS，不能删除或格式化；</li><li>约 250 GB 的 <code>CachyOS</code> ExFAT 分区是安装目标。</li></ul><p>分区编号可能因设备而异，应以名称、文件系统和容量共同判断，不能只照抄编号。</p><h2 id="_6-关闭-t2-安全启动限制" tabindex="-1">6. 关闭 T2 安全启动限制 <a class="header-anchor" href="#_6-关闭-t2-安全启动限制" aria-label="Permalink to &quot;6. 关闭 T2 安全启动限制&quot;">​</a></h2><ol><li>关闭 Mac；</li><li>开机后立即按住 <code>Command + R</code>，进入 macOS 恢复模式；</li><li>选择管理员账户并输入密码；</li><li>打开“实用工具” -&gt; “启动安全性实用工具”；</li><li>将安全启动设置为 <code>无安全性（No Security）</code>；</li><li>选择 <code>允许从外部或可移动介质启动</code>。</li></ol><p>详细说明参见 <a href="https://support.apple.com/102522" target="_blank" rel="noreferrer">Apple 启动安全性实用工具</a>。</p><p>安装完成后可以重新禁止从外部介质启动，但运行 CachyOS 通常仍需保持 <code>No Security</code>。</p><h2 id="_7-启动-cachyos-live-环境" tabindex="-1">7. 启动 CachyOS Live 环境 <a class="header-anchor" href="#_7-启动-cachyos-live-环境" aria-label="Permalink to &quot;7. 启动 CachyOS Live 环境&quot;">​</a></h2><ol><li>插入 CachyOS U 盘；</li><li>重启 Mac，并立即按住 <code>Option</code>；</li><li>在 Apple Startup Manager 中选择橙色的 <code>EFI Boot</code>；</li><li>如果出现两个 <code>EFI Boot</code>，可先尝试最右侧的一个；</li><li>进入 CachyOS Live 桌面。</li></ol><p>如果出现“需要软件更新才能使用此启动磁盘”，通常表示安全启动设置没有生效，或者选择了错误的 <code>EFI Boot</code>。</p><h2 id="_8-live-环境联网" tabindex="-1">8. Live 环境联网 <a class="header-anchor" href="#_8-live-环境联网" aria-label="Permalink to &quot;8. Live 环境联网&quot;">​</a></h2><p>CachyOS 使用在线安装器，安装时必须联网。</p><p>如果已有 USB 网卡或 USB 网络共享，可以直接使用，并在安装完成后再导入 Apple 固件。</p><p>如果安装阶段只能使用内置 Wi-Fi，先确认 Apple EFI 分区：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">lsblk</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -f</span></span></code></pre></div><p>T2 Mac 的 Apple EFI 通常是 <code>/dev/nvme0n1p1</code>，容量约 300 MB、文件系统为 FAT32。确认后执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> mkdir</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -p</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> /tmp/apple-wifi-efi</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> mount</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> /dev/nvme0n1p1</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> /tmp/apple-wifi-efi</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">bash</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> /tmp/apple-wifi-efi/firmware.sh</span></span></code></pre></div><p>脚本询问固件来源时选择：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>1. Retrieve the firmware from the EFI partition.</span></span></code></pre></div><p>即输入 <code>1</code> 并按回车。脚本完成后执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> umount</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> /tmp/apple-wifi-efi</span></span></code></pre></div><p>注意：Live 环境是临时系统。在 Live 环境中导入固件后，安装完成进入正式系统时仍需再执行一次。</p><h2 id="_9-安装-cachyos" tabindex="-1">9. 安装 CachyOS <a class="header-anchor" href="#_9-安装-cachyos" aria-label="Permalink to &quot;9. 安装 CachyOS&quot;">​</a></h2><h3 id="_9-1-选择-bootloader" tabindex="-1">9.1 选择 Bootloader <a class="header-anchor" href="#_9-1-选择-bootloader" aria-label="Permalink to &quot;9.1 选择 Bootloader&quot;">​</a></h3><p>在安装器的 Bootloader 页面选择：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>systemd-boot</span></span></code></pre></div><p>本文不复用 Apple 原有约 300 MB 的 EFI，而是在 CachyOS 空间中创建独立的 2 GB FAT32 <code>/boot</code> 分区。这样可以满足 CachyOS 对 systemd-boot 启动分区的容量要求，也能避免修改 Apple EFI。</p><h3 id="_9-2-手动分区" tabindex="-1">9.2 手动分区 <a class="header-anchor" href="#_9-2-手动分区" aria-label="Permalink to &quot;9.2 手动分区&quot;">​</a></h3><p>选择 <code>Manual partitioning</code>，然后：</p><ol><li>找到之前创建的约 250 GB ExFAT <code>CachyOS</code> 分区；</li><li>只删除这个 ExFAT 分区，使其变为空闲空间；</li><li>在空闲空间中新建 2048 MiB FAT32 分区；</li><li>将该 FAT32 分区挂载到 <code>/boot</code>，并启用 <code>boot</code> 标志；</li><li>使用剩余空间创建 Btrfs 分区，挂载到 <code>/</code>；</li><li>不修改 Apple EFI；</li><li>不修改 macOS APFS 分区。</li></ol><p>本次验证成功的最终布局如下：</p><table tabindex="0"><thead><tr><th>分区</th><th style="text-align:right;">大小</th><th>文件系统</th><th>挂载点</th><th>操作</th></tr></thead><tbody><tr><td>Apple EFI</td><td style="text-align:right;">约 300 MiB</td><td>FAT32</td><td>无</td><td>保留，不格式化</td></tr><tr><td>macOS</td><td style="text-align:right;">约 232.81 GiB</td><td>APFS</td><td>无</td><td>保留，不格式化</td></tr><tr><td>Boot</td><td style="text-align:right;">2 GiB</td><td>FAT32</td><td><code>/boot</code></td><td>新建，设置 boot 标志</td></tr><tr><td>CachyOS</td><td style="text-align:right;">约 230.81 GiB</td><td>Btrfs</td><td><code>/</code></td><td>新建并安装系统</td></tr></tbody></table><p>安装摘要应当只包含：</p><ul><li>删除原 CachyOS ExFAT 分区；</li><li>创建 2048 MiB FAT32 <code>/boot</code>；</li><li>创建 Btrfs 系统分区；</li><li>在 Btrfs 分区安装 CachyOS。</li></ul><p>如果摘要显示将格式化约 300 MB 的 Apple EFI 或 macOS APFS，应立即返回检查，不能继续安装。</p><h3 id="_9-3-其他安装选项" tabindex="-1">9.3 其他安装选项 <a class="header-anchor" href="#_9-3-其他安装选项" aria-label="Permalink to &quot;9.3 其他安装选项&quot;">​</a></h3><p>按需要设置时区、键盘、桌面环境、软件包和用户账户，然后开始安装。安装器中的 CachyOS Hardware Detection 应自动应用必要的 T2 启动参数和配置。</p><p>安装结束后重启。需要手动选择系统时，开机按住 <code>Option</code>：</p><ul><li>macOS 仍从原来的 macOS 启动项进入；</li><li>CachyOS 通常显示为 <code>EFI Boot</code>。</li></ul><h2 id="_10-在正式系统中安装-wi-fi-和蓝牙固件" tabindex="-1">10. 在正式系统中安装 Wi-Fi 和蓝牙固件 <a class="header-anchor" href="#_10-在正式系统中安装-wi-fi-和蓝牙固件" aria-label="Permalink to &quot;10. 在正式系统中安装 Wi-Fi 和蓝牙固件&quot;">​</a></h2><p>首次进入新安装的 CachyOS 后，打开终端执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> mkdir</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -p</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> /tmp/apple-wifi-efi</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> mount</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> /dev/nvme0n1p1</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> /tmp/apple-wifi-efi</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">bash</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> /tmp/apple-wifi-efi/firmware.sh</span></span></code></pre></div><p>出现以下选择时输入 <code>1</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>How do you want to copy the firmware to Linux?</span></span>
<span class="line"><span>1. Retrieve the firmware from the EFI partition.</span></span></code></pre></div><p>脚本安装并重新加载 Wi-Fi、蓝牙驱动后，会询问是否继续在 EFI 中保留固件和脚本：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>Do you want to keep a copy? (y/N)</span></span></code></pre></div><p>输入 <code>y</code>，以便以后重装或修复。脚本结束后卸载 EFI：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> umount</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> /tmp/apple-wifi-efi</span></span></code></pre></div><p>检查网络设备：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">nmcli</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> device</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> status</span></span></code></pre></div><p>正常情况下会出现 Wi-Fi 设备，并且 KDE 网络菜单能够扫描无线网络。</p><h3 id="_10-1-wi-fi-仍未出现" tabindex="-1">10.1 Wi-Fi 仍未出现 <a class="header-anchor" href="#_10-1-wi-fi-仍未出现" aria-label="Permalink to &quot;10.1 Wi-Fi 仍未出现&quot;">​</a></h3><p>先让 NetworkManager 使用 iwd 后端：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> mkdir</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -p</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> /etc/NetworkManager/conf.d</span></span>
<span class="line"><span style="--shiki-light:#D20F39;--shiki-light-font-style:italic;--shiki-dark:#F38BA8;--shiki-dark-font-style:italic;">printf</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> &#39;[device]\\nwifi.backend=iwd\\n&#39;</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;"> |</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> tee</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> /etc/NetworkManager/conf.d/wifi_backend.conf</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> systemctl</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> restart</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> NetworkManager</span></span></code></pre></div><p>仍未出现时重新加载内核模块：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> modprobe</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -r</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> brcmfmac_wcc</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> modprobe</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -r</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> brcmfmac</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> modprobe</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> brcmfmac</span></span></code></pre></div><p>不要安装 <code>broadcom-wl</code>。T2 Mac 使用从 macOS 提取的 Apple 固件和内核中的 <code>brcmfmac</code> 驱动。</p><h2 id="_11-更新和验证" tabindex="-1">11. 更新和验证 <a class="header-anchor" href="#_11-更新和验证" aria-label="Permalink to &quot;11. 更新和验证&quot;">​</a></h2><p>联网后更新系统：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> pacman</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -Syu</span></span></code></pre></div><p>测试网络：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">ping</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -c</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> 4</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> archlinux.org</span></span></code></pre></div><p>最后重启：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">reboot</span></span></code></pre></div><p>重启后检查以下项目：</p><ul><li>按 <code>Option</code> 可以分别进入 macOS 和 CachyOS；</li><li>Wi-Fi 重启后仍能使用；</li><li>蓝牙能够扫描设备；</li><li>键盘、触控板、Touch Bar、声音和亮度调节正常；</li><li>合盖睡眠和恢复没有导致系统失去响应。</li></ul><h2 id="_12-常见问题" tabindex="-1">12. 常见问题 <a class="header-anchor" href="#_12-常见问题" aria-label="Permalink to &quot;12. 常见问题&quot;">​</a></h2><h3 id="启动-u-盘时提示需要软件更新" tabindex="-1">启动 U 盘时提示需要软件更新 <a class="header-anchor" href="#启动-u-盘时提示需要软件更新" aria-label="Permalink to &quot;启动 U 盘时提示需要软件更新&quot;">​</a></h3><p>重新进入恢复模式，确认安全启动是 <code>No Security</code>，并允许从外部介质启动。如果启动菜单中有两个 <code>EFI Boot</code>，尝试另一个。</p><h3 id="安装器提示-efi-分区太小" tabindex="-1">安装器提示 EFI 分区太小 <a class="header-anchor" href="#安装器提示-efi-分区太小" aria-label="Permalink to &quot;安装器提示 EFI 分区太小&quot;">​</a></h3><p>不要扩大或格式化 Apple 原有约 300 MB 的 EFI。按照本文方案，从 CachyOS 目标空间单独创建 2 GB FAT32 <code>/boot</code>，并选择 systemd-boot。</p><h3 id="固件脚本没有自动运行" tabindex="-1">固件脚本没有自动运行 <a class="header-anchor" href="#固件脚本没有自动运行" aria-label="Permalink to &quot;固件脚本没有自动运行&quot;">​</a></h3><p>这是正常现象。macOS 中执行 <code>copy_to_efi</code> 只负责保存固件。进入 Live 环境或正式系统后，需要挂载 Apple EFI 并运行其中的 <code>firmware.sh</code>。</p><h3 id="重启后-wi-fi-再次消失" tabindex="-1">重启后 Wi-Fi 再次消失 <a class="header-anchor" href="#重启后-wi-fi-再次消失" aria-label="Permalink to &quot;重启后 Wi-Fi 再次消失&quot;">​</a></h3><p>确认固件脚本是在正式安装的 CachyOS 中执行，而不是只在 Live 环境中执行。之后检查：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">nmcli</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> device</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> status</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">ls</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> /lib/firmware/brcm</span></span></code></pre></div><h3 id="amd-独显不稳定" tabindex="-1">AMD 独显不稳定 <a class="header-anchor" href="#amd-独显不稳定" aria-label="Permalink to &quot;AMD 独显不稳定&quot;">​</a></h3><p><code>MacBookPro16,1</code> 带 Intel 核显和 AMD 独显，Linux 下的混合显卡支持仍不完整。不要一开始就永久添加 <code>nomodeset</code>，因为它会禁用正常的图形加速。遇到黑屏或崩溃时，应记录内核日志，并参考 <a href="https://wiki.t2linux.org/guides/hybrid-graphics/" target="_blank" rel="noreferrer">t2linux Hybrid Graphics 指南</a>针对具体显卡处理。</p><h2 id="_13-参考资料" tabindex="-1">13. 参考资料 <a class="header-anchor" href="#_13-参考资料" aria-label="Permalink to &quot;13. 参考资料&quot;">​</a></h2><ul><li><a href="https://wiki.cachyos.org/installation/installation_t2macbook/" target="_blank" rel="noreferrer">CachyOS: T2 MacBook 安装指南</a></li><li><a href="https://wiki.cachyos.org/installation/installation_prepare/" target="_blank" rel="noreferrer">CachyOS: 安装准备与 U 盘制作</a></li><li><a href="https://wiki.cachyos.org/installation/installation_on_root/" target="_blank" rel="noreferrer">CachyOS: Desktop/Laptop 安装与手动分区</a></li><li><a href="https://wiki.t2linux.org/guides/preinstall/" target="_blank" rel="noreferrer">t2linux: 安装前准备</a></li><li><a href="https://wiki.t2linux.org/state/" target="_blank" rel="noreferrer">t2linux: 设备支持状态</a></li><li><a href="https://support.apple.com/103265" target="_blank" rel="noreferrer">Apple: 配备 T2 安全芯片的 Mac</a></li><li><a href="https://support.apple.com/102522" target="_blank" rel="noreferrer">Apple: 启动安全性实用工具</a></li></ul><hr><p>本文记录于 2026 年 8 月。CachyOS 是滚动发行版，安装器界面、ISO 文件名和固件脚本选项可能随版本变化。执行涉及磁盘的操作前，应以安装摘要中实际显示的分区名称、容量和文件系统为准。</p>`,133)]))}const y=a(l,[["render",p]]);export{k as __pageData,y as default};
